/* Explain the system before running the cases; keep the fourteen established section URLs. */
const abRetrieval=articles.find(a=>a.id==='agent-retrieval');
abRetrieval.sections[0]=['检索、上下文与最终主张是怎样连接的',
 para('检索从资料中找出候选内容；索引是为寻找资料建立的数据结构；上下文是本次模型调用实际看到的输入。检索增强生成（RAG）把取回的材料加入上下文，辅助模型回答。候选相关、正文获准交付、回答得到支持，是需要分别验证的三件事。',
 '一条常见路径是：解析问题，召回候选，核对正文与来源，重排和去重，在预算内装配输入，生成回答，最后检查主张与引用。重排改变候选顺序，装配决定哪部分真的进入输入；排名靠前却没被装进去的材料，无法为本次回答提供内容。',
 '先用一份简单费用问题连起这些对象：A租户的基础费用a-1/v1为10，调整费用a-2/v2为27，v1/v2分别表示版本1/版本2。任务要求给出总额并保留两份来源。两份都在且适用于本月，独立参考总额才是37。另一租户的999、调整项的旧版99，或只取到27，都不足以回答这个任务。')+
 figure('v47-context-path','本章把索引、权威正文、装配器与接收端分开。最终发送前再核对授权和版本；接收端确实收到的材料另有记录。')+
 para('这份数值夹具让证据是否完整可以独立检查；第十五节实际执行检索、词元计数和本地请求交付，不运行语言模型。后面另用排障题和分级标签说明评估指标的边界，不能把固定算术成功率当成真实模型回答质量。')];
abRetrieval.sections[1]=['片段、版本与来源：先保留能追回原文的身份',
 para('文档是来源对象，片段是从文档切出、可以单独召回的内容单位。分片需要保留足够的语义条件，例如金额单位、适用月份和“仅在某版本有效”的限定。按固定字数切开后只留下27，可能丢掉它属于调整费用还是历史值的说明。重叠片段也不能当成两份独立证据重复计数。',
 '给片段保留文档ID、版本、片段位置与内容摘要。ID帮助找对象，版本区分历史状态，位置定位引用范围，SHA256等摘要算法用内容计算固定长度的指纹，帮助检查字节是否改变。摘要匹配证明两份内容一致，不证明内容真实、当前有效或读者有权访问。来源归属与授权仍需由可信系统核对。')+
 table(['本章对象','作用','容易混淆的结果'],[['a-2/v1：99','保存过的历史材料','不能用文件存在证明适用本月'],['a-2/v2：27','本次正常任务需要的版本','索引命中后仍要取得相同正文'],['SHA256摘要','核对候选与被读内容是否一致','不替代签发、事实核验或授权'],['引用定位','让读者看见支撑这句话的片段','只给文档标题不证明支持具体主张']])+
 para('索引、正文和实际引用可能在不同时间形成。记录“候选来自哪版、装配取了哪版、最后引用哪版”，才能定位更新途中发生的混用。删除、撤权和缓存命中也要沿这份身份传播；来源变了，不能只保留原来的好看标题。')];
abRetrieval.sections[4]=['召回范围、候选数量与证据齐备要分开',
 para('召回负责提出可能相关的对象，候选数量k只表示这轮最多保留多少项，不表示必要证据一定齐备。实际查询还受租户、当前版本和读取资格限制。若先取全局前两项，再删掉越权项，合法候选可能全部消失；在合法范围内找候选，可以避免这一种预算浪费，但仍需评价完整证据是否被找到。',
 '过滤元数据与交付正文是不同观察。可信服务内部搜索全局索引，不等于已经把全局正文交给当前任务；如果把B租户正文送进A任务上下文后再删除展示项，交付已经发生。应记录正文实际跨过了哪个边界，不能只看最后输出列表没有B。',
 '访问控制列表（ACL）规定对象的访问资格；本例用固定主体的资源读取资格记录表示它。新实验的FTS5查询先按A租户、当前版本与读取资格限制，取正文时再次核对候选版本。这是数据库里的固定策略，不是完整企业身份平台。旧版a-2/v1和跨租户b-1/v1即使被人为放进候选，也会在正文获取处拒绝。')+
 table(['阶段','本例应保留的事实','能发现的故障'],[['候选','a-1/v1、a-2/v2','少召回、旧索引或范围不符'],['正文','相同版本、摘要与获准内容','候选和正文错配或撤权'],['上下文','两份必要证据均进入','预算把其中一份挤掉'],['接收端','实际请求与版本清单','装配成功却发出另一份输入'],['回答','37和两份有效来源','材料齐备仍生成错值或错引']])];
abRetrieval.sections[5]=['完整词元预算：正文、模板与输出预留一起算',
 para('分词器规定文本怎样映成词元编号，词元数不等于汉字数、字符数或UTF-8字节数。本节使用固定版本tiktoken 0.12.0与cl100k_base编码。字节对编码（BPE）通过逐步合并字节或子词片段形成词元；一个汉字或一个表情也可能跨多个词元。换分词器、模板或模型协议后，不能直接沿用原来的计数。',
 '先定义实际发送的输入。本实验把系统约束、任务、来源ID/版本/摘要、正文和分隔文字序列化成一条固定字符串，再整体编码。两段正文分开编码共36词元，完整输入是237；只数正文会漏掉来源与模板。分段计数之和也未必恰好等于整段编码结果，因为边界处的合并可能不同。')+
 knowledgeFormula('本实验自定义的窗口账','输入237 + 输出预留96 = 333 ≤ 声明窗口512；剩余179','512是本实验给定预算，不是任何真实模型的窗口规格；237针对这份纯字符串模板，不包含未定义的聊天消息封装。对接真实后端应按实际协议计数。')+
 figure('v47-context-token-budget','同一编码与完整模板：正常两份证据237词元；预算收紧到259后，只容163词元输入与96预留，少一份必要证据，拒绝发送。')+
 para('装配器每加入一段，就重新编码整份候选输入，确认没有超限；本例优先整段保留，不把关键条件切碎。预算缩到259后，只留下a-2/v2的27，另一份基础费用没有进入。候选阶段两份都找到，最终上下文却只覆盖一半，程序按“证据不足”停止，接收端请求数为0。',
 '按词元切片也要注意字符边界。“中国🙂恢复”的前两个词元含完整“中国”和表情的一半字节，默认解码会出现替换字符；退回严格有效边界只保留“中国”。这样修好了编码，却仍可能截掉事实或条件。对证据应优先按有意义的段落、句子或结构选择，截短后重新检查是否足以支持任务。')+
 figure('v47-context-token-bytes','实际词元ID与对应字节。第2个词元只含🙂的前两个UTF-8字节，不能把每个词元当成完整字符。')+
 para('源文出现类似特殊结束标记的字符串时，本程序把它当普通文本编码，不让它变成这个编码器的控制词元。这只处理编码契约；内容中写着“忽略权限”仍是不可信材料，不能因此获得授权。真实模型是否服从恶意材料需要另外评估，不能由本地词元测试推断。')];
abRetrieval.sections[6][0]='排序指标与任务证据：换一道排障题核对';
abRetrieval.sections[6][1]=para('换一道排障题R27：林问“今天变慢是否由昨天的配置更新引起”。需要延迟时间线、变更时间和适用版本说明三份不同证据。本节以这个任务展示“第一条更准”为什么可能同时让完整覆盖变差；它的分母与前面的两项费用任务不同。')+abRetrieval.sections[6][1].replace('迁移到原R27','迁移到排障题R27');
abRetrieval.sections[8]=['授权复检：可信装配器与模型输入之间还有一道边界',
 para('正文在取回时获准，不代表以后每次复用都永久获准。缓存键应区分租户、主体或适当权限范围、来源与版本；命中缓存后仍要按协议判断当前资格。把授权信息写在文档正文里，或者让材料自称属于A，不能替代服务端的归属记录。',
 '本章新实验先在可信装配器内取回两份正文，再通过另一个SQLite连接撤销a-2的读取资格。指定的发送前检查点发现变化，拒绝交付，真实HTTP提示收集器没有收到这份请求。这里的边界是“装配器内持有”到“发送给接收端”，不是声称任何情况下都能撤回模型已经读过的内容。',
 '检查与外部HTTP之间仍没有跨系统原子性：如果权限在检查之后、发送过程中改变，还需规定在途请求语义、短期授权与后端实施点。本地前置复检覆盖了本次注入窗口，不提供全球即时撤权。工具授权章同样按实际产生效果的边界讨论这个问题。',
 '权限失败时不能为了保持答案完整而偷用旧摘要、旧缓存或历史引用副本。已有输出也可能需要受控撤回或重新取证，但不能假设删除一条索引就消除了所有副本。应把候选、可信内部读取、模型实际输入和用户可见结果分别留有合适的审计记录。')];
abRetrieval.sections[9]=['版本推进与索引滞后：旧值27不能悄悄变成新证据',
 para('正常任务需要a-2/v2的27。装配后，来源推进到v3，调整费用变成30。即使旧正文、摘要和链接都仍然完整，发送前也会因当前版本变化拒绝旧包。本实验采用“引用当前版本”的规则；若产品允许历史快照，应另写清任务时间与历史读取资格，不能暗中在两种规则之间切换。',
 '更新正文不会自动更新索引。实验把current指针切到v3而FTS仍只有v2，新的合规查询会暂时排除a-2，只剩a-1；实际把v3加入索引后，两份证据恢复齐备。此时独立参考总额是10+30=40，不能从旧答案缓存直接取回37。这里验证了新鲜证据，不代表语言模型已经生成过40。')+
 table(['观察','应该怎样解释'],[['正文v3、索引v2','索引投影滞后；本协议暂不交付旧命中'],['候选v2、实际正文v3','不是同一份证据；重取/重排并重新装配'],['摘要匹配旧v2','只证明旧内容一致，不能说明当前有效'],['重建后拿到v3','重新计数、核对来源与任务结果'],['撤权后仍有缓存','缓存存在不提供新的访问资格']])+
 para('新鲜度可以按更新时间、索引推进与实际引用版本观测，但不能只报一个“同步成功”。先说明版本由谁产生、哪些变化会更新版本，以及删除、权限变化与正文变化分别怎样传播，再用实际读取的ID/版本和内容核对。')];
abRetrieval.sections[10]=['引用要同时满足定位、支持与读取资格',
 para('引用不是给答案附一个看似相关的链接。至少应能定位这份材料的具体版本和片段，材料实际支持所写主张，而且当前查看者有权读取。费用答案37应绑定a-1/v1的10与a-2/v2的27；只引“费用说明”标题，不能让人核对算式和适用月份。',
 '来源中的数值、单位、否定与例外条件应一起保留。若材料说“调整27只在本月有效”，回答成“以后每月都加27”就是扩大主张；把多份重复片段当成多方佐证也会夸大证据。先按主张拆解所需支持，再检查每份实际输入和引用，不用语言流畅度替代核验。',
 '历史引用需要标注当时版本。文档更新后，直接把旧链接跳到新正文，可能让读者误解旧结论；可在权限允许时提供明确历史视图。无法继续提供时显示不可访问状态，保留受控审计线索，而不是向已撤权主体展示旧副本。',
 '把故障定位到阶段：候选是否找到，正文是否同版且获准，上下文是否保全必要证据，真正发出的请求是否一致，生成结果是否正确且受支持。第十五节的收集器只证明请求和来源确实送达；真实LLM答案质量、引用支持率与无答案拒绝，还需独立样本和实际模型运行。')+
 '<p>'+linkTo('agent-evaluation','继续区分任务、证据与评分器的独立判据')+'</p>'];
abRetrieval.sections[12][1]=para('本节用固定分数、规则重排与人为预算单位，隔离“候选齐备却没有完整进入上下文”的问题。这里的16/12不是模型词元数；第十五节再对完整字符串模板做真实BPE计数，两份记录的预算口径分别保存。')+abRetrieval.sections[12][1];
abRetrieval.sections.push(['实战：完整BPE预算、版本复检与实际提示交付',
 para('本实验实际建立FTS5索引、取正文、调用固定BPE编码器，并向回环HTTP收集器发送最终提示。它不运行LLM，也不将材料传给外部模型服务。先安装固定依赖；词表首次从官方来源准备到缓存，网络慢时会等待，后续实验仅用本地资源。')+
 agentBoundaryRun('context_budget.py','context-budget-run','python3 -m venv .venv\n.venv/bin/python -m pip install -r requirements.txt\n.venv/bin/python context_budget.py --report context-local.json')+
 table(['实际用例','结果','接收端新增请求'],[['正常a-1/v1与a-2/v2','完整输入237；正文单计36；独立参考37','1'],['预算259、输入上限163','缺a-1，证据不足','0'],['取回后撤权','authorization_changed','0'],['取回后来源推进v3','source_version_changed','0'],['索引仍旧→加入v3','缺a-2→两份齐备；新参考40','0（仅核对新证据）'],['跨租户/旧版本候选','正文获取拒绝','0'],['截前2个词元','中国�；退到有效边界为中国','编码反例，未发送']])+
 para('查看receiver：实际只收到正常的一份请求，来源为a-2/v2与a-1/v1，完整提示摘要与发送前一致。再看cases：候选都找到的紧预算用例，真正入选只剩一份；材料已经取回的两种变化，最终仍无请求送达。把这些阶段分别核对，才能知道“检索成功”之后究竟发生了什么。')]);
abRetrieval.sections[4][1]='<div class="mechanism-core" id="retrieval-evidence-pipeline">'+abRetrieval.sections[4][1]+'</div>';
